INSERT IGNORE INTO promotion_bid (
    id, campaign_id, auction_window_id, bidder_user_id, bid_amount, wallet_business_ref, command_id, decision_id,
    decision_status, projection_offset, status, clearing_price, slot_index, created_at, updated_at
