mapper.select:
SELECT *
FROM promotion_bid
WHERE campaign_id = #{campaignId}
  AND auction_window_id = #{auctionWindowId}
LIMIT 1

SELECT b.*, c.post_id AS post_id
FROM promotion_bid b
         LEFT JOIN promotion_campaign c ON c.id = b.campaign_id
WHERE b.auction_window_id = #{auctionWindowId}
  AND b.status = 'ACTIVE'
  AND c.status = 'ACTIVE'
  AND c.start_at <= #{allocationStartAt}
  AND c.end_at >= #{allocationEndAt}
ORDER BY b.bid_amount DESC, b.id ASC
